import { loadFont } from "@remotion/google-fonts/SpaceGrotesk";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// ARENNA RUN v2 (cliente "marra"). Mesma locução da v1 (src/voz-v1-corte.wav), visual refeito "parecido com o do João Victor
// e o do AR Studio" (HigiGestorV2 e AbdomeFullHd): base escura com batidas de cor que invertem o fundo na abertura, letra
// grotesca reta e pesada com a palavra-chave numa pílula, passos numerados com ícone num cartão escuro, cantos de visor e,
// no fim, o botão tocado por um cursor. Só o jeito vem das referências: cores, logo e letra são da Arenna
// (azul #0052FF, marinho, Space Grotesk, a fonte do site arenna.run).
// Fio: a linha do percurso (embolada na pergunta, reta de ponta a ponta, trilha dos serviços, linha final do logo).
// Tonoflash: logo + três fotos de corrida públicas do Instagram @suamarca dentro do visor, cada uma com um clique.
// Tempos = tempos da locução cortada (t = 0 no começo da voz; o vídeo tem LEAD de entrada).

const { fontFamily: F } = loadFont("normal", { weights: ["500", "700"], subsets: ["latin", "latin-ext"] });

export const AR2_FPS = 30;
const LEAD = 0.25;
export const AR2_FRAMES = Math.round(42.3 * AR2_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.25));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));

const INK = "#050B1C";
const PANEL = "#0E1730";
const BLUE = "#0052FF";
const BLUE_L = "#5C8DFF";
const NAVY = "#08173A";
const WHITE = "#FFFFFF";
const MIST = "#F3F5FA";
const LINE = "#DDE3EE";
const SOFT = "#93A0C2";
const YELLOW = "#FFDD33";

const T2 = 3.1, T3 = 8.12, T4 = 16.78, T5 = 19.05, T6 = 26.5, T7 = 32.52, T8 = 36.45;

// ───────── texto pela máscara: cada linha nasce de baixo de uma linha invisível e fica parada ─────────
type L = [string, number, boolean?];
const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; color?: string; out?: number; pillBg?: string; pillText?: string }> = ({ t, items, size, top, color = WHITE, out, pillBg = BLUE, pillText = WHITE }) => {
  const o = out === undefined ? 0 : lin(t, out, out + 0.16);
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap: size * 0.1, opacity: 1 - o, filter: o > 0 ? `blur(${(o * 10).toFixed(1)}px)` : undefined }}>
      {items.map(([w, at, hl], i) => {
        const e = k(t, at, 0.5);
        return (
          <div key={i} style={{ overflow: "hidden", padding: `0 ${size * 0.1}px ${size * 0.06}px`, ...(hl ? { borderRadius: size * 0.3, transform: `scale(${(0.86 + 0.14 * pop(t, at, 0.5)).toFixed(4)})` } : {}) }}>
            <div style={{ fontFamily: F, fontWeight: 700, fontSize: size, lineHeight: 1.1, letterSpacing: "-0.045em", whiteSpace: "nowrap", color: hl ? pillText : color, transform: `translateY(${((1 - e) * 112).toFixed(2)}%)`, ...(hl ? { background: pillBg, padding: `${size * 0.02}px ${size * 0.26}px ${size * 0.1}px`, borderRadius: size * 0.26 } : {}) }}>
              {w}
            </div>
          </div>
        );
      })}
    </div>
  );
};
const W: React.FC<{ t: number; at: number; size: number; color?: string; text: string }> = ({ t, at, size, color = WHITE, text }) => {
  const e = k(t, at, 0.42);
  return (
    <div style={{ overflow: "hidden", padding: `0 ${size * 0.06}px ${size * 0.1}px` }}>
      <div style={{ fontFamily: F, fontWeight: 700, fontSize: size, lineHeight: 1.06, letterSpacing: "-0.055em", whiteSpace: "nowrap", color, transform: `translateY(${((1 - e) * 115).toFixed(2)}%)` }}>{text}</div>
    </div>
  );
};
const Col: React.FC<{ children: React.ReactNode; top?: number }> = ({ children, top }) => (
  <div style={{ position: "absolute", left: 120, right: 120, ...(top === undefined ? { top: 0, bottom: 0, justifyContent: "center" } : { top }), display: "flex", flexDirection: "column", alignItems: "center" }}>{children}</div>
);
const Cam: React.FC<{ t: number; a: number; b: number; s0?: number; s1?: number; y?: number; children: React.ReactNode }> = ({ t, a, b, s0 = 1, s1 = 1.05, y = 0, children }) => {
  const p = lin(t, a - 0.4, b + 0.4);
  return <AbsoluteFill style={{ transform: `translateY(${(y * p).toFixed(1)}px) scale(${(s0 + (s1 - s0) * p).toFixed(4)})` }}>{children}</AbsoluteFill>;
};

// ───────── ícones ─────────
type Ico = React.FC<{ s: number; c: string; w?: number }>;
const sv = (s: number, c: string, w: number, ch: React.ReactNode) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round">{ch}</svg>
);
const IcoArte: Ico = ({ s, c, w = 1.8 }) => sv(s, c, w, <><rect x="6" y="2.5" width="12" height="19" rx="2.6" /><rect x="8.4" y="5.8" width="7.2" height="7.2" rx="1.2" /><path d="M8.4 11.6l2.2-2 1.7 1.5 1.3-1.1 2 1.8" /><path d="M10.6 17.8h2.8" /></>);
const IcoTicket: Ico = ({ s, c, w = 1.8 }) => sv(s, c, w, <><path d="M3 7h18v3.2a1.8 1.8 0 000 3.6V17H3v-3.2a1.8 1.8 0 000-3.6z" /><path d="M15 7.5v1.4M15 11.3v1.4M15 15.1v1.4" /><path d="M6.5 11h5M6.5 13.5h3.5" /></>);
const IcoStaff: Ico = ({ s, c, w = 1.8 }) => sv(s, c, w, <><circle cx="9" cy="8" r="3.2" /><path d="M3 20c.6-3.6 3-5.6 6-5.6s5.4 2 6 5.6" /><circle cx="17" cy="9" r="2.5" /><path d="M17.2 14.4c2.2.3 3.4 2.2 3.8 5" /></>);
const IcoKit: Ico = ({ s, c, w = 1.8 }) => sv(s, c, w, <><path d="M4.5 8.5h15l-1.4 12h-12.2z" /><path d="M8.8 8.5V7a3.2 3.2 0 016.4 0v1.5" /><path d="M9 13.5l2 2 4-4" /></>);
const IcoMedal: Ico = ({ s, c, w = 1.8 }) => sv(s, c, w, <><path d="M8 2.5l4 7 4-7" /><circle cx="12" cy="15.2" r="5.6" /><path d="M12 12.4l.9 1.8 2 .3-1.45 1.4.35 2-1.8-.95-1.8.95.35-2-1.45-1.4 2-.3z" /></>);
const IcoArco: Ico = ({ s, c, w = 1.8 }) => sv(s, c, w, <><path d="M4 21V8.5M20 21V8.5" /><rect x="2.5" y="4" width="19" height="4.5" rx="1.2" /><path d="M6.5 6.25h11" strokeDasharray="1.6 1.6" /><path d="M2.5 21h4M17.5 21h4" /></>);
const IcoCheck: Ico = ({ s, c, w = 2.4 }) => sv(s, c, w, <path d="M5 12.5l4.5 4.5L19 7.5" />);

const SERVICES: [Ico, string, string, number][] = [
  [IcoArte, "Artes para", "o Instagram", 8.36],
  [IcoTicket, "Lançamento", "e vendas", 9.19],
  [IcoStaff, "Staffs", "", 11.1],
  [IcoKit, "Confecção e", "entrega de kits", 12.45],
  [IcoMedal, "Medalhas", "", 14.3],
  [IcoArco, "Estrutura", "", 15.6],
];

// ───────── a linha do percurso ─────────
const routePts = (u: number, x0: number, x1: number, y: number, t: number, R0 = 130) => {
  const n = 220;
  const pts: [number, number][] = [];
  for (let i = 0; i <= n; i++) {
    const s = i / n;
    const env = Math.sin(Math.PI * s) ** 0.6;
    const R = R0 * (1 - u) * env;
    const ph = 2 * Math.PI * 4.5 * s + t * 0.8 * (1 - u);
    pts.push([x0 + (x1 - x0) * s + R * Math.cos(ph) * 1.15, y + R * Math.sin(ph) * 0.95 + (1 - u) * 30 * Math.sin(s * 9 + t * 1.3) * env]);
  }
  return pts;
};
const ptsToD = (pts: [number, number][]) => "M" + pts.map(([x, y]) => `${x.toFixed(1)} ${y.toFixed(1)}`).join(" L");
const pathLen = (pts: [number, number][]) => pts.reduce((a, p, i) => (i ? a + Math.hypot(p[0] - pts[i - 1][0], p[1] - pts[i - 1][1]) : 0), 0);
const Flag: React.FC<{ s: number; c?: string; bg?: string }> = ({ s, c = NAVY, bg = WHITE }) => (
  <svg width={s} height={s * 1.3} viewBox="0 0 20 26">
    <path d="M3 25V2" stroke={c} strokeWidth={2.4} strokeLinecap="round" />
    {[0, 1, 2].map((r) => [0, 1, 2, 3].map((q) => <rect key={`${r}${q}`} x={4 + q * 3.6} y={2.4 + r * 3.6} width={3.6} height={3.6} fill={(r + q) % 2 ? bg : c} />))}
    <rect x={4} y={2.4} width={14.4} height={10.8} fill="none" stroke={c} strokeWidth={1} />
  </svg>
);
// cantos de visor (o fio do AR Studio, aqui na cena da Tonoflash)
const Corners: React.FC<{ w: number; h: number; c: string; len?: number; th?: number }> = ({ w, h, c, len = 90, th = 10 }) => {
  const st = (rot: number): React.CSSProperties => ({ position: "absolute", width: len, height: len, borderLeft: `${th}px solid ${c}`, borderTop: `${th}px solid ${c}`, borderTopLeftRadius: 26, transform: `rotate(${rot}deg)` });
  return (
    <div style={{ position: "absolute", inset: 0, width: w, height: h }}>
      <div style={{ ...st(0), left: 0, top: 0 }} />
      <div style={{ ...st(90), right: 0, top: 0 }} />
      <div style={{ ...st(180), right: 0, bottom: 0 }} />
      <div style={{ ...st(270), left: 0, bottom: 0 }} />
    </div>
  );
};

// ───────── cena 1 · a pergunta em batidas: o fundo inverte a cada batida ─────────
const B1 = -0.2, B2 = 0.36, B3 = 1.05, B4 = 1.7;
const S1: React.FC<{ t: number }> = ({ t }) => {
  const ats = [B1, B2, B3, B4];
  const beat = t < B2 ? 0 : t < B3 ? 1 : t < B4 ? 2 : 3;
  const punch = (i: number) => (1 + 0.14 * (1 - k(t, ats[i], 0.5))) * (1 + 0.035 * lin(t, ats[i], ats[i] + 0.9));
  const clipFor = (i: number) => {
    const p = io(t, ats[i], ats[i] + 0.2);
    if (p >= 1 || i === 0) return undefined;
    if (i === 1) return `circle(${(p * 120).toFixed(1)}% at 50% 50%)`;
    if (i === 2) return `polygon(0 0, ${(p * 170).toFixed(1)}% 0, ${(p * 170 - 60).toFixed(1)}% 100%, 0 100%)`;
    return `inset(${((1 - p) * 50).toFixed(2)}% 0 ${((1 - p) * 50).toFixed(2)}% 0)`;
  };
  const layer = (i: number, bg: string, body: React.ReactNode) =>
    beat === i || (beat === i + 1 && io(t, ats[i + 1], ats[i + 1] + 0.2) < 1) ? (
      <AbsoluteFill key={i} style={{ background: bg, clipPath: clipFor(i) }}>
        <AbsoluteFill style={{ transform: `scale(${punch(i).toFixed(4)})` }}>{body}</AbsoluteFill>
      </AbsoluteFill>
    ) : null;
  // a linha embolada, desenhando-se embaixo da pergunta
  const pts = routePts(0, 190, 890, 1240, t, 120);
  const len = pathLen(pts);
  const draw = k(t, B4 + 0.1, 1.3);
  return (
    <AbsoluteFill style={{ background: INK }}>
      {layer(0, INK, (
        <Col>
          <W t={t} at={-0.15} size={170} text="Está com" />
        </Col>
      ))}
      {layer(1, BLUE, (
        <Col>
          <W t={t} at={B2 + 0.03} size={150} text="dificuldades" />
        </Col>
      ))}
      {layer(2, WHITE, (
        <Col>
          <W t={t} at={B3 + 0.02} size={110} color={NAVY} text="de planejar" />
        </Col>
      ))}
      {layer(3, INK, (
        <>
          <Col top={560}>
            <W t={t} at={B4 + 0.02} size={110} color={SOFT} text="a sua" />
            <div style={{ marginTop: 6, background: WHITE, borderRadius: 50, padding: "0 40px", opacity: Math.min(1, pop(t, B4 + 0.12, 0.4) * 3), transform: `scale(${(0.7 + 0.3 * pop(t, B4 + 0.12, 0.4)).toFixed(4)})` }}>
              <W t={t} at={B4 + 0.14} size={150} color={BLUE} text="corrida?" />
            </div>
          </Col>
          <svg width={1080} height={1920} style={{ position: "absolute", inset: 0 }}>
            <path d={ptsToD(pts)} fill="none" stroke={WHITE} strokeWidth={12} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={`${(len * draw).toFixed(1)} ${(len + 10).toFixed(0)}`} opacity={0.9} />
            <circle cx={190} cy={1240} r={24 * pop(t, B4 + 0.1, 0.4)} fill={BLUE} stroke={INK} strokeWidth={8} />
          </svg>
        </>
      ))}
    </AbsoluteFill>
  );
};

// ───────── cena 2 · a Arenna cuida de tudo, de ponta a ponta ─────────
const S2: React.FC<{ t: number }> = ({ t }) => {
  const X0 = 170, X1 = 910, Y = 1260;
  const u = io(t, 3.35, 4.9);
  const pts = routePts(u, X0, X1, Y, t, 120);
  const run = io(t, 5.7, 6.75);
  const dotI = Math.min(pts.length - 1, Math.round(run * (pts.length - 1)));
  const flag = pop(t, 6.6, 0.5);
  const logo = k(t, 3.2, 0.55);
  return (
    <AbsoluteFill style={{ background: MIST }}>
      <Cam t={t} a={T2} b={T3} s0={1.05} s1={1} y={-10}>
        <div style={{ position: "absolute", left: 120, right: 120, top: 380, display: "flex", justifyContent: "center", clipPath: `inset(-20px ${((1 - logo) * 100).toFixed(2)}% -20px 0)` }}>
          <Img src={staticFile("marra/logo-arenna.png")} style={{ width: 760, transform: `translateX(${((1 - logo) * -60).toFixed(1)}px)` }} />
        </div>
        <Lines t={t} top={610} size={88} color={NAVY} items={[["cuida de tudo", 3.62], ["por você", 4.4, true]]} />
        <svg width={1080} height={1920} style={{ position: "absolute", inset: 0 }}>
          <path d={ptsToD(pts)} fill="none" stroke={u > 0.5 ? BLUE : NAVY} strokeWidth={14} strokeLinecap="round" strokeLinejoin="round" />
          {run > 0 ? <path d={ptsToD(pts.slice(0, dotI + 1))} fill="none" stroke={NAVY} strokeWidth={14} strokeLinecap="round" /> : null}
          <circle cx={X0} cy={Y} r={26} fill={BLUE} stroke={MIST} strokeWidth={8} />
          {run > 0 && run < 1 ? <circle cx={pts[dotI][0]} cy={pts[dotI][1]} r={22} fill={NAVY} stroke={MIST} strokeWidth={6} /> : null}
        </svg>
        <div style={{ position: "absolute", left: X1 - 14, top: Y - 132, transformOrigin: "14px 132px", transform: `scale(${flag.toFixed(3)}) rotate(${(-8 * bump(t, 6.7, 0.6) + (t > 7 ? Math.sin((t - 7) * 5) * 4 : 0)).toFixed(2)}deg)` }}>
          <Flag s={100} bg={MIST} />
        </div>
        {([[X0, "Largada", 5.66], [X1, "Chegada", 6.55]] as const).map(([x, l, at]) => (
          <div key={l} style={{ position: "absolute", left: x - 150, width: 300, top: Y + 56, textAlign: "center", fontFamily: F, fontWeight: 700, fontSize: 40, color: NAVY, letterSpacing: "-0.03em", opacity: k(t, at, 0.35), transform: `translateY(${((1 - k(t, at, 0.35)) * 20).toFixed(1)}px)` }}>{l}</div>
        ))}
        <Lines t={t} top={1480} size={92} color={NAVY} items={[["de ponta a ponta", 5.66, true]]} />
      </Cam>
    </AbsoluteFill>
  );
};

// ───────── cena 3 · os serviços em passos numerados (jeito do AR Studio) ─────────
const S3: React.FC<{ t: number }> = ({ t }) => {
  const DX0 = 190, DX1 = 890, DY = 420;
  const prog = SERVICES.reduce((a, s, i) => a + io(t, s[3] - 0.05, s[3] + 0.35) * (i === 0 ? 0 : 1), 0) / (SERVICES.length - 1);
  return (
    <AbsoluteFill style={{ background: INK }}>
      <Cam t={t} a={T3} b={T4} s0={1} s1={1.045} y={-12}>
        <svg width={1080} height={1920} style={{ position: "absolute", inset: 0, opacity: k(t, T3 + 0.1, 0.4) }}>
          <line x1={DX0} y1={DY} x2={DX1} y2={DY} stroke="rgba(255,255,255,0.16)" strokeWidth={4} />
          <line x1={DX0} y1={DY} x2={DX0 + (DX1 - DX0) * prog} y2={DY} stroke={BLUE} strokeWidth={4} />
        </svg>
        {SERVICES.map((s, i) => {
          const x = DX0 + ((DX1 - DX0) * i) / (SERVICES.length - 1);
          const on = t >= s[3] - 0.05;
          const b = bump(t, s[3], 0.4);
          return (
            <div key={i} style={{ position: "absolute", left: x - 30, top: DY - 30, width: 60, height: 60, borderRadius: 60, background: on ? BLUE : INK, border: `3px solid ${on ? BLUE : "rgba(255,255,255,0.35)"}`, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F, fontWeight: 700, fontSize: 26, color: on ? WHITE : SOFT, opacity: k(t, T3 + 0.1 + i * 0.05, 0.4), transform: `scale(${(1 + 0.25 * b).toFixed(3)})` }}>{i + 1}</div>
          );
        })}
        {SERVICES.map(([I, a1, a2, at], i) => {
          const end = i + 1 < SERVICES.length ? SERVICES[i + 1][3] - 0.05 : 1e9;
          if (t < at - 0.1 || t >= end) return null;
          const e = pop(t, at - 0.08, 0.5);
          return (
            <React.Fragment key={i}>
              <div style={{ position: "absolute", left: 540 - 140, top: 640, width: 280, height: 280, borderRadius: 70, background: PANEL, border: "2px solid rgba(92,141,255,0.35)", display: "flex", alignItems: "center", justifyContent: "center", opacity: Math.min(1, e * 3), transform: `translateY(${(Math.sin((t - at) * 2.4) * 10).toFixed(1)}px) scale(${(0.6 + 0.4 * e).toFixed(4)}) rotate(${((1 - e) * -14).toFixed(2)}deg)` }}>
                <I s={170} c={BLUE_L} w={1.7} />
              </div>
              <Lines t={t} top={1000} size={86} color={BLUE} items={[[String(i + 1).padStart(2, "0"), at]]} />
              <Lines t={t} top={1110} size={a2 ? 104 : 124} items={(a2 ? [[a1, at + 0.06], [a2, at + 0.16]] : [[a1, at + 0.06]]) as L[]} />
            </React.Fragment>
          );
        })}
      </Cam>
    </AbsoluteFill>
  );
};

// ───────── cena 4 · tudo o que um evento precisa: a grade se fecha (jeito do João Victor) ─────────
const S4: React.FC<{ t: number }> = ({ t }) => {
  const G = 230, GAP = 30;
  return (
    <AbsoluteFill style={{ background: BLUE }}>
      <Cam t={t} a={T4} b={T5} s0={1.06} s1={1}>
        <Lines t={t} top={330} size={96} items={[["Tudo o que", 16.95], ["um evento", 17.25]]} />
        <Lines t={t} top={575} size={96} pillBg={WHITE} pillText={BLUE} items={[["precisa", 17.55, true]]} />
        {SERVICES.map(([I], i) => {
          const r = Math.floor(i / 3), c = i % 3;
          const at = T4 + 0.15 + ((i * 4) % 6) * 0.08;
          const e = io(t, at, at + 0.4);
          const ent = pop(t, T4 + 0.05 + i * 0.04, 0.4);
          const sx = [-300, 260, -120, 340, -360, 180][i], sy = [-260, -330, 280, 120, -40, 320][i], sr = [-38, 24, 52, -20, 30, -48][i];
          const gx = (c - 1) * (G + GAP), gy = r * (G + GAP);
          const done = pop(t, 18.0 + i * 0.07, 0.35);
          return (
            <div key={i} style={{ position: "absolute", left: 540 + gx + sx * (1 - e) * 0.9 - G / 2, top: 900 + gy + sy * (1 - e) * 0.8, width: G, height: G, borderRadius: 56, background: e > 0.98 ? WHITE : "rgba(255,255,255,0.22)", border: "3px solid rgba(255,255,255,0.55)", boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", opacity: Math.min(1, ent * 2), transform: `rotate(${(sr * (1 - e)).toFixed(2)}deg) scale(${(ent * (1 + 0.08 * bump(t, at + 0.4, 0.3))).toFixed(4)})` }}>
              <I s={130} c={NAVY} w={1.7} />
              <div style={{ position: "absolute", right: -14, top: -14, width: 64, height: 64, borderRadius: 64, background: NAVY, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${done.toFixed(3)})` }}><IcoCheck s={40} c={WHITE} /></div>
            </div>
          );
        })}
      </Cam>
    </AbsoluteFill>
  );
};

// ───────── cena 5 · quem já corre com a gente ─────────
const CLIENTS: [string, string, string, number][] = [
  ["elas.jpg", "av-elas.jpg", "Elas Run", 21.02],
  ["flores.jpg", "av-flores.jpg", "Circuito das Flores", 21.5],
  ["patria.jpg", "av-patria.jpg", "Corrida pela Pátria", 22.6],
  ["cristo.jpg", "av-cristo.jpg", "Correndo com Cristo", 24.0],
];
const FAN = 25.75;
const S5: React.FC<{ t: number }> = ({ t }) => {
