  [-9, S1, () => "none"],
  [T2, S2, (p) => `circle(${(p * 125).toFixed(1)}% at 50% 49%)`],
  [T3, S3, (p) => `inset(${((1 - p) * 100).toFixed(2)}% 0 0 0)`],
  [T4, S4, (p) => `polygon(0 0, ${(p * 170).toFixed(1)}% 0, ${(p * 170 - 60).toFixed(1)}% 100%, 0 100%)`],
  [T5, S5, (p) => `circle(${(p * 125).toFixed(1)}% at 50% 80%)`],
  [T6, S6, (p) => `inset(0 ${((1 - p) * 50).toFixed(2)}% 0 ${((1 - p) * 50).toFixed(2)}%)`],
  [T7, S7, (p) => `inset(0 0 ${((1 - p) * 100).toFixed(2)}% 0)`],
  [T8, S8, (p) => `inset(0 0 0 ${((1 - p) * 100).toFixed(2)}%)`],
];

export const ArennaV2: React.FC = () => {
  const t = useCurrentFrame() / AR2_FPS - LEAD;
  return (
    <AbsoluteFill style={{ background: INK }}>
      {SCENES.map(([at, S, clip], i) => {
        const end = i + 1 < SCENES.length ? SCENES[i + 1][0] + 0.45 : 1e9;
        if (t < at || t >= end) return null;
        const p = i === 0 ? 1 : interpolate(t, [at, at + 0.42], [0, 1], { ...cl, easing: INOUT });
        return (
          <AbsoluteFill key={i} style={p < 1 ? { clipPath: clip(p) } : undefined}>
            <S t={t} />
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

